function validate([mountain]) {
  if (!Array.isArray(mountain) || mountain.length < 3 || mountain.length > 100) return 'mountain needs 3 to 100 values.';
  if (mountain.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each height is an integer from 1 to 100.';
  return null;
}

