function findPeaks(mountain) {
  const peaks = [];
  for (let i = 1; i < mountain.length - 1; i++) {
    const left = mountain[i - 1];
    const right = mountain[i + 1];
    if (mountain[i] > left && mountain[i] > right) {
      peaks.push(i);
    }
  }
  return peaks;
}

