function findPeaks(mountain) {
  const last = mountain.length - 1;
  return mountain
    .map((value, index) => ({ value, index }))
    .filter(({ value, index }) => index !== 0 && index !== last)
    .filter(({ value, index }) => [mountain[index - 1], mountain[index + 1]].every(other => other < value))
    .map(({ index }) => index)
    .reverse();
}

